1	package zkcircuit
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// These tests pin the job-id identity rule, the job counterpart of the
12	// circuit-name rule in name_encoding_test.go: an id is a job's identity, so it
13	// must keep one exact value across submit, save, read and lookup.
14	//
15	// On the write path an id that is not complete, valid UTF-8 (a lone
16	// continuation byte, a truncated multi-byte character, an encoded surrogate
17	// half) is refused as ErrInvalidArgument before anything is committed —
18	// encoding/json would otherwise silently rewrite those bytes to U+FFFD at
19	// save time, a later GetJob by the submitted bytes would miss the record, and
20	// it could share an identity with an id that genuinely contains "�".
21	//
22	// On the read path a committed job record whose raw id token carries invalid
23	// UTF-8 bytes, or \uXXXX escapes forming an unpaired surrogate — under the
24	// canonical "id" or an ASCII case/JSON-escaped spelling — is data corruption:
25	// the whole directory read fails with ErrDataCorrupt naming the job record
26	// (by position when the id cannot be recovered) and the id field, no partial
27	// results are returned, and the file stays byte-for-byte in place. Legal
28	// Chinese, emoji, an actually committed "�", a legal surrogate pair and the
29	// literal six characters \uD800 are all ordinary ids and keep their exact
30	// value.
31	
32	// rawJobEnvelope builds a complete committed envelope around one legal job
33	// plus one job record whose id is the given raw JSON string token (already
34	// quoted/escaped by the caller). The frozen circuit c v1 has a trusted setup
35	// so the records are semantically legal apart from the damaged id.
36	func rawJobEnvelope(idJSON string) []byte {
37		return []byte(`{"format":1,"circuits":[` +
38			`{"name":"c","version":1,"constraints":1,"public_inputs":1,"private_inputs":1,"frozen":true,"description":""}` +
39			`],"setups":[{"name":"c","version":1}],"jobs":[` +
40			`{"id":"j1","circuit":"c","version":1,"kind":"prove","attempt":1},` +
41			`{"id":` + idJSON + `,"circuit":"c","version":1,"kind":"prove","attempt":1}` +
42			`]}`)
43	}
44	
45	// SubmitJob refuses every shape of invalid UTF-8 in the id with
46	// ErrInvalidArgument, writes nothing, and leaves an already registered job
47	// readable under its own id.
48	func TestSubmitJobRejectsInvalidUTF8ID(t *testing.T) {
49		dir := t.TempDir()
50		s, err := Open(dir)
51		if err != nil {
52			t.Fatal(err)
53		}
54		defer s.Close()
55		h := compiledVersion(t, s, "c", 1, validDef)
56		if _, err := s.SubmitJob(boundProveJob("j1", "c", 1, h)); err != nil {
57			t.Fatal(err)
58		}
59		dataPath := filepath.Join(dir, dirDataFile)
60		before, err := os.ReadFile(dataPath)
61		if err != nil {
62			t.Fatal(err)
63		}
64	
65		bad := map[string]string{
66			"lone continuation byte":   "bad\x80id",
67			"truncated multi-byte":     "trunc\xe4\xb8",
68			"overlong encoding":        "over\xc0\xaf",
69			"invalid byte 0xff":        "bad\xff",
70			"encoded surrogate half":   "pair\xed\xa0\x80",
71			"truncated at end":         "end\xc3",
72			"continuation then ASCII":  "bad\x80x",
73			"valid prefix then damage": "作业\xff",
74		}
75		for label, id := range bad {
76			t.Run(label, func(t *testing.T) {
77				_, err := s.SubmitJob(boundProveJob(id, "c", 1, h))
78				if !errors.Is(err, ErrInvalidArgument) {
79					t.Fatalf("want ErrInvalidArgument, got %v", err)
80				}
81				if !strings.Contains(err.Error(), "UTF-8") {
82					t.Fatalf("error does not explain the id encoding is invalid: %v", err)
83				}
84			})
85		}
86	
87		after, err := os.ReadFile(dataPath)
88		if err != nil {
89			t.Fatal(err)
90		}
91		if string(after) != string(before) {
92			t.Fatalf("refused submissions modified data.json\nwant: %q\n got: %q", before, after)
93		}
94		// Neither the submitted bytes nor their U+FFFD-repaired form may exist as
95		// a job; the existing job stays readable under its own id.
96		if got, err := s.GetJob("j1"); err != nil || got.ID != "j1" {
97			t.Fatalf("existing job damaged by refused submissions: %+v %v", got, err)
98		}
99		jobs, err := s.ListJobs()
100		if err != nil {
101			t.Fatal(err)
102		}
103		if len(jobs) != 1 || jobs[0].ID != "j1" {
104			t.Fatalf("refused submissions left jobs behind: %+v", jobs)
105		}
106	}
107	
108	// Legal Unicode ids submit, save, reopen and read back under their exact
109	// submitted value, and idempotent resubmit / conflicting resubmit keep their
110	// existing behavior on those ids.
111	func TestSubmitJobValidUnicodeIDsRoundTrip(t *testing.T) {
112		dir := t.TempDir()
113		s, err := Open(dir)
114		if err != nil {
115			t.Fatal(err)
116		}
117		h := compiledVersion(t, s, "c", 1, validDef)
118		ids := []string{
119			"作业-1",          // Chinese
120			"emoji 😀 job",   // emoji
121			"has�mark",      // an actually committed replacement character
122			`literal\uD800`, // the literal six characters \uD800 — no escape
123			"mixed 作业😀�mix",
124		}
125		for _, id := range ids {
126			if _, err := s.SubmitJob(boundProveJob(id, "c", 1, h)); err != nil {
127				t.Fatalf("submit %q: %v", id, err)
128			}
129		}
130		// Same id + same request is idempotent; same id + different request
131		// conflicts — identity stays byte-exact for Unicode ids.
132		if _, err := s.SubmitJob(boundProveJob(ids[0], "c", 1, h)); err != nil {
133			t.Fatalf("idempotent resubmit %q: %v", ids[0], err)
134		}
135		conflicting := boundProveJob(ids[0], "c", 1, "")
136		if _, err := s.SubmitJob(conflicting); !errors.Is(err, ErrConflict) {
137			t.Fatalf("different request under same id: want ErrConflict, got %v", err)
138		}
139		if err := s.Close(); err != nil {
140			t.Fatal(err)
141		}
142	
143		s2, err := Open(dir)
144		if err != nil {
145			t.Fatal(err)
146		}
147		defer s2.Close()
148		for _, id := range ids {
149			got, err := s2.GetJob(id)
150			if err != nil {
