152			}
153			if got.ID != id {
154				t.Fatalf("id changed across save and read: want %q, got %q", id, got.ID)
155			}
156		}
157		listed, err := s2.ListJobs()
158		if err != nil {
159			t.Fatal(err)
160		}
161		if len(listed) != len(ids) {
162			t.Fatalf("want %d jobs, got %+v", len(ids), listed)
163		}
164	}
165	
166	// A committed id with invalid UTF-8 bytes is data corruption even when legal
167	// jobs share the directory: the read fails outright, names the job record
168	// (positionally — the id cannot be recovered) and the id field, and leaves
169	// the file byte-for-byte in place.
170	func TestCorruptJobIDInvalidUTF8Refused(t *testing.T) {
171		bad := map[string]string{
172			"lone continuation byte":   "\"bad\x80id\"",
173			"invalid byte 0xff":        "\"bad\xff\"",
174			"truncated multi-byte":     "\"trunc\xe4\xb8\"",
175			"overlong encoding":        "\"over\xc0\xaf\"",
176			"encoded surrogate half":   "\"pair\xed\xa0\x80\"",
177			"valid prefix then damage": "\"作业\xff\"",
178		}
179		for label, idJSON := range bad {
180			t.Run(label, func(t *testing.T) {
181				raw := rawJobEnvelope(idJSON)
182				dir := plantRawEnvelope(t, raw)
183	
184				s, err := Open(dir)
185				if err == nil {
186					s.Close()
187					t.Fatalf("directory with an invalid-UTF-8 job id was accepted")
188				}
189				if !errors.Is(err, ErrDataCorrupt) {
190					t.Fatalf("want ErrDataCorrupt, got %v", err)
191				}
192				if !strings.Contains(err.Error(), "job record #2") ||
193					!strings.Contains(err.Error(), `"id"`) {
194					t.Fatalf("error does not name the job record and the id field: %v", err)
195				}
196				left, rerr := os.ReadFile(filepath.Join(dir, dirDataFile))
197				if rerr != nil {
198					t.Fatal(rerr)
199				}
200				if string(left) != string(raw) {
201					t.Fatalf("refused read modified data.json\nwant: %q\n got: %q", raw, left)
202				}
203			})
204		}
205	}
206	
207	// A committed id whose JSON escapes form an unpaired surrogate is data
208	// corruption under the same rules as a circuit name.
209	func TestCorruptJobIDUnpairedSurrogateRefused(t *testing.T) {
210		bad := map[string]string{
211			"lone high surrogate":            `"作业\uD800"`,
212			"lone low surrogate":             `"\uDC00"`,
213			"high surrogate at end":          `"end\uD83D"`,
214			"two high surrogates":            `"\uD800\uD800"`,
215			"high then non-surrogate escape": `"\uD800A"`,
216			"high then simple escape":        `"\uD800\n"`,
217			"low then high (reversed pair)":  `"\uDC00\uD800"`,
218			"low surrogate after valid pair": `"😀\uDE00"`,
219			"escaped lowercase":              `"a\ud800"`,
220		}
221		for label, idJSON := range bad {
222			t.Run(label, func(t *testing.T) {
223				raw := rawJobEnvelope(idJSON)
224				dir := plantRawEnvelope(t, raw)
225	
226				s, err := Open(dir)
227				if err == nil {
228					s.Close()
229					t.Fatalf("directory with an unpaired-surrogate job id was accepted")
230				}
231				if !errors.Is(err, ErrDataCorrupt) {
232					t.Fatalf("want ErrDataCorrupt, got %v", err)
233				}
234				if !strings.Contains(err.Error(), "job record #2") ||
235					!strings.Contains(err.Error(), `"id"`) {
236					t.Fatalf("error does not name the job record and the id field: %v", err)
237				}
238				left, rerr := os.ReadFile(filepath.Join(dir, dirDataFile))
239				if rerr != nil {
240					t.Fatal(rerr)
241				}
242				if string(left) != string(raw) {
243					t.Fatalf("refused read modified data.json\nwant: %q\n got: %q", raw, left)
244				}
245			})
246		}
247	}
248	
249	// The id encoding rule applies to every spelling the ordinary decode fills ID
250	// from — an ASCII case variant ("ID") and a JSON-\u-escaped spelling of the
251	// key — and a damaged id that is the only job in the file is located by its
252	// record position. Byte-bearing values are built by concatenation so the JSON
253	// text keeps the \uXXXX key escapes while the value carries raw bad bytes.
254	func TestCorruptJobIDSpellingVariantsRefused(t *testing.T) {
255		jobTail := `,"circuit":"c","version":1,"kind":"prove","attempt":1}`
256		cases := []struct {
257			label  string
258			record string
259		}{
260			{"case variant ID with invalid bytes", `{"ID":"bad` + "\xff" + `"` + jobTail},
261			{"case variant ID with lone surrogate", `{"ID":"bad\uD800"` + jobTail},
262			{`\u-escaped "id" key with invalid bytes`, "{\"\\u0069\\u0064\":\"bad" + "\xff" + "\"" + jobTail},
263			{`\u-escaped "ID" key with lone surrogate`, "{\"\\u0049\\u0044\":\"bad\\uD800\"" + jobTail},
264			{"only job with invalid bytes", `{"id":"only` + "\xff" + `"` + jobTail},
265		}
266		for _, tc := range cases {
267			t.Run(tc.label, func(t *testing.T) {
268				raw := []byte(`{"format":1,"circuits":[` +
269					`{"name":"c","version":1,"constraints":1,"public_inputs":1,"private_inputs":1,"frozen":true,"description":""}` +
270					`],"setups":[{"name":"c","version":1}],"jobs":[` + tc.record + `]}`)
271				dir := plantRawEnvelope(t, raw)
272	
273				_, err := Open(dir)
274				if !errors.Is(err, ErrDataCorrupt) {
275					t.Fatalf("want ErrDataCorrupt, got %v", err)
276				}
277				if !strings.Contains(err.Error(), "job record #1") ||
278					!strings.Contains(err.Error(), `"id"`) {
279					t.Fatalf("error does not name the positional record and the id field: %v", err)
280				}
281				left, rerr := os.ReadFile(filepath.Join(dir, dirDataFile))
282				if rerr != nil {
283					t.Fatal(rerr)
284				}
285				if string(left) != string(raw) {
286					t.Fatalf("refused read modified data.json")
287				}
288			})
289		}
290	}
291	
292	// Legal id encodings read back under their exact value: a surrogate pair
293	// decodes to its astral character, a committed "�" (direct or U+FFFD-escaped)
294	// is an ordinary id, and the literal text \uD800 carries no escape at all.
295	func TestLegalJobIDEncodingsReadBackExactly(t *testing.T) {
296		cases := map[string]struct {
297			idJSON string
298			want   string
299		}{
300			"surrogate pair decodes to its character": {`"job-😀"`, "job-😀"},
301			"escaped Chinese":                         {`"job-作业"`, "job-作业"},
302			"escaped backslash keeps literal text":    {`"x\\uD800"`, `x\uD800`},
303			"committed replacement char direct":       {"\"has�mark\"", "has�mark"},
304			"committed replacement char escaped":      {`"has�mark"`, "has�mark"},
305		}
306		for label, tc := range cases {
307			t.Run(label, func(t *testing.T) {
308				raw := []byte(`{"format":1,"circuits":[` +
309					`{"name":"c","version":1,"constraints":1,"public_inputs":1,"private_inputs":1,"frozen":true,"description":""}` +
310					`],"setups":[{"name":"c","version":1}],"jobs":[` +
311					`{"id":` + tc.idJSON + `,"circuit":"c","version":1,"kind":"prove","attempt":1}]}`)
312				dir := plantRawEnvelope(t, raw)
313	
314				s, err := Open(dir)
315				if err != nil {
316					t.Fatalf("legal id refused: %v", err)
317				}
318				defer s.Close()
319				got, err := s.GetJob(tc.want)
