1	package main
2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8	)
9	
10	// CLI contract for an ambiguous owning circuit on a committed job record.
11	// Every spelling an ordinary read would take as the job's circuit —
12	// canonical "circuit", an ASCII letter-case variant such as "CIRCUIT" or
13	// "CiRcUiT", or a JSON-escaped spelling of either — is one circuit field.
14	// Two of them on one record make the owning circuit depend on key order, so
15	// every data command fails at open with exit code 3, prints no record,
16	// names the damaged job and its circuit field, and leaves data.json
17	// byte-for-byte in place. A single recognized spelling still reads.
18	
19	// seedTwoCircuitJobCLI drives the CLI through two legal create + freeze +
20	// setup sequences (alpha and beta) and one unbound job-submit owned by
21	// alpha, reproducing the ambiguity that matters: j1 spelled against either
22	// circuit has a valid owner.
23	func seedTwoCircuitJobCLI(t *testing.T, dir string) {
24		t.Helper()
25		must := func(what string, r cliResult) {
26			t.Helper()
27			if r.code != 0 {
28				t.Fatalf("%s: code=%d err=%s", what, r.code, r.err)
29			}
30		}
31		for _, name := range []string{"alpha", "beta"} {
32			must("create "+name, callCLI(t, "circuit-create", "--dir", dir, "--name", name, "--version", "1",
33				"--constraints", "1", "--public-inputs", "1", "--private-inputs", "1"))
34			must("freeze "+name, callCLI(t, "circuit-freeze", "--dir", dir, "--name", name, "--version", "1"))
35			must("setup "+name, callCLI(t, "setup-record", "--dir", dir, "--name", name, "--version", "1"))
36		}
37		must("submit", callCLI(t, "job-submit", "--dir", dir, "--id", "j1", "--name", "alpha", "--version", "1"))
38	}
39	
40	// rewriteJobCircuitCLI scopes a literal replacement to the committed j1 job:
41	// it replaces the first old occurring after the j1 id marker, so no other
42	// record's fields are ever touched. It returns the bytes now on disk.
43	func rewriteJobCircuitCLI(t *testing.T, dir, old, fragment string) []byte {
44		t.Helper()
45		path := filepath.Join(dir, "data.json")
46		raw, err := os.ReadFile(path)
47		if err != nil {
48			t.Fatal(err)
49		}
50		marker := `"id": "j1"`
51		at := strings.Index(string(raw), marker)
52		if at < 0 {
53			t.Fatalf("committed file does not carry the j1 marker %q", marker)
54		}
55		rel := strings.Index(string(raw[at:]), old)
56		if rel < 0 {
57			t.Fatalf("j1 job does not carry %q after its id marker", old)
58		}
59		pos := at + rel
60		bad := []byte(string(raw[:pos]) + fragment + string(raw[pos+len(old):]))
61		if err := os.WriteFile(path, bad, 0o644); err != nil {
62			t.Fatal(err)
63		}
64		return bad
65	}
66	
67	// TestCLIJobCircuitAmbiguousExitCode: two recognized circuit spellings on j1
68	// — ASCII variants or JSON-escaped spellings, equal or differing values, in
69	// either key order — make every data command exit 3 with no output and leave
70	// data.json byte-for-byte in place.
71	func TestCLIJobCircuitAmbiguousExitCode(t *testing.T) {
72		escC := cliJSONEscape + "u0063ircuit"
73		cases := []struct {
74			name     string
75			fragment string
76		}{
77			{"canonical plus upper, same value", `"circuit": "alpha", "CIRCUIT": "alpha"`},
78			{"canonical plus upper, differing", `"circuit": "alpha", "CIRCUIT": "beta"`},
79			{"upper then canonical", `"CIRCUIT": "beta", "circuit": "alpha"`},
80			{"mixed case", `"circuit": "alpha", "CiRcUiT": "alpha"`},
81			{"escaped exact spelling", `"circuit": "alpha", "` + escC + `": "alpha"`},
82		}
83		for _, tc := range cases {
84			t.Run(tc.name, func(t *testing.T) {
85				dir := filepath.Join(t.TempDir(), "bench")
86				seedTwoCircuitJobCLI(t, dir)
87				bad := rewriteJobCircuitCLI(t, dir, `"circuit": "alpha"`, tc.fragment)
88	
89				commands := [][]string{
90					{"job-get", "--dir", dir, "--id", "j1"},
91					{"job-list", "--dir", dir},
92					{"job-submit", "--dir", dir, "--id", "j2", "--name", "alpha", "--version", "1"},
93					{"circuit-list", "--dir", dir},
94					{"circuit-create", "--dir", dir, "--name", "other", "--version", "1"},
95				}
96				for _, args := range commands {
97					r := callCLI(t, args...)
98					if r.code != 3 {
99						t.Fatalf("%s: want exit 3, got %d (out=%q err=%q)", args[0], r.code, r.out, r.err)
100					}
101					if r.out != "" {
102						t.Fatalf("%s printed a record despite corruption: %q", args[0], r.out)
103					}
104					if !strings.Contains(r.err, "read failed") || !strings.Contains(r.err, "data corrupt") {
105						t.Fatalf("%s: unexpected error text %q", args[0], r.err)
106					}
107					if !strings.Contains(r.err, `"j1"`) || !strings.Contains(r.err, "circuit") {
108						t.Fatalf("%s: error does not name the damaged job and circuit field: %q", args[0], r.err)
109					}
110				}
111	
112				left, err := os.ReadFile(filepath.Join(dir, "data.json"))
113				if err != nil {
114					t.Fatal(err)
115				}
116				if string(left) != string(bad) {
117					t.Fatalf("data.json changed after refused commands")
118				}
119			})
120		}
121	}
122	
123	// TestCLIJobCircuitSingleSpellingStillReads: one recognized spelling of
124	// circuit, canonical or an ASCII case variant, direct or JSON-escaped, keeps
125	// the job owned by alpha.
126	func TestCLIJobCircuitSingleSpellingStillReads(t *testing.T) {
127		escC := cliJSONEscape + "u0063ircuit"
128		for _, tc := range []struct {
129			name string
130			key  string
131		}{
132			{"upper case", "CIRCUIT"},
133			{"mixed case", "CiRcUiT"},
134			{"escaped letter", escC},
135		} {
136			t.Run(tc.name, func(t *testing.T) {
137				dir := filepath.Join(t.TempDir(), "bench")
138				seedTwoCircuitJobCLI(t, dir)
139				rewriteJobCircuitCLI(t, dir, `"circuit": "alpha"`, `"`+tc.key+`": "alpha"`)
140	
141				r := callCLI(t, "job-get", "--dir", dir, "--id", "j1")
142				if r.code != 0 {
143					t.Fatalf("single spelling %q must load: code=%d err=%s", tc.key, r.code, r.err)
144				}
145				if !strings.Contains(r.out, "circuit=alpha") || !strings.Contains(r.out, "version=1") {
146					t.Fatalf("single spelling %q not read as owned by alpha v1: %q", tc.key, r.out)
147				}
148			})
149		}
150	}
